#!/usr/bin/env python3
"""Regenerate sounds.js from the files in SoundLibrary/.

Run this whenever sounds are added to or removed from SoundLibrary:
    python3 make_sound_list.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
LIBRARY = ROOT / "SoundLibrary"
EXTENSIONS = {".wav", ".m4a", ".mp3", ".aif", ".aiff", ".ogg", ".flac"}

files = sorted(
    p.name for p in LIBRARY.iterdir()
    if p.is_file() and p.suffix.lower() in EXTENSIONS
)

(ROOT / "sounds.js").write_text(
    "// Generated by make_sound_list.py. Do not edit by hand.\n"
    "window.SOUND_LIBRARY = " + json.dumps(files, indent=2) + ";\n"
)
print(f"Wrote {len(files)} sounds to sounds.js")
